document.addEventListener("DOMContentLoaded",function(){function e(e){return e>=1e6?`$${(e/1e6).toFixed(1)}M`:e>=1e3?`$${(e/1e3).toFixed(0)}K`:e.toLocaleString("en-US",{style:"currency",currency:"USD",minimumFractionDigits:0,maximumFractionDigits:0})}function n(e){return`${e.toFixed(1)}%`}function t(e,n,t,a="info"){return`\n      <div class="insight-card ${a}">\n        <h6>${e}</h6>\n        <div class="metric-value">${n}</div>\n        <div class="metric-subtitle">${t}</div>\n      </div>\n    `}const a=document.getElementById("cafe-form"),s=document.getElementById("cafe-result");a&&a.addEventListener("submit",function(a){a.preventDefault();const i=parseFloat(document.getElementById("area").value),l=parseFloat(document.getElementById("seats").value),c=parseFloat(document.getElementById("equipment-cost").value),o=parseFloat(document.getElementById("renovation-cost").value),r=parseFloat(document.getElementById("furniture-cost").value),d=parseFloat(document.getElementById("additional-costs").value),u=parseFloat(document.getElementById("monthly-rent").value),m=parseFloat(document.getElementById("avg-check").value),p=parseFloat(document.getElementById("clients-per-day").value),v=parseFloat(document.getElementById("working-days").value),f=parseFloat(document.getElementById("staff-salaries").value),y=parseFloat(document.getElementById("cogs-percent").value),g=c+o+r+d,$=m*p*v,h=$*(y/100),b=u+f+h+parseFloat(document.getElementById("utilities").value)+parseFloat(document.getElementById("other-expenses").value),B=$-b,w=12*$,E=12*B,F=B>0?g/B/12:0,I=B>0?E/g*100:0,k=$>0?B/$*100:0,P=p/(4*l)*100,C=$/i;let x="warning",A="Needs Optimization";I>=20&&k>=15?(x="success",A="High Profit Business"):I>=12&&k>=8&&(x="info",A="Stable Business");let D=[];k<10&&(D.push("📈 Increase average transaction with premium menu items"),D.push("💰 Optimize food costs (target 25-30% of revenue)")),P<50&&(D.push("🎯 Attract more customers through marketing and loyalty programs"),D.push("⏰ Extend operating hours or add delivery services")),C<50&&(D.push("🏢 Consider smaller space to reduce rent costs"),D.push("📦 Add takeaway format to increase turnover")),m<8&&(D.push("☕ Offer specialty coffee drinks and desserts"),D.push("🥐 Expand breakfast and light lunch menu"));s.innerHTML=`\n        <div class="business-plan-results">\n          <h3>☕ Café Business Plan Analysis</h3>\n          \n          <div class="insight-cards">\n          ${t("💰 Total Investment",e(g),"Initial Capital","info")}\n          ${t("📈 Monthly Revenue",e($),`${p} customers × $${m} × ${v} days`,"success")}\n          ${t("💸 Monthly Expenses",e(b),`Including ${n(y)} COGS`,"warning")}\n          ${t("💵 Net Profit",e(B),`Margin: ${n(k)}`,x)}\n          ${t("⏳ Payback Period",`${F.toFixed(1)} years`,F<3?"Fast Payback":F<5?"Moderate Payback":"Slow Payback",F<3?"success":F<5?"info":"warning")}\n          ${t("📊 ROI",n(I),A,x)}\n        </div>\n\n        <div class="analysis-section">\n          <h4>📋 Detailed Analysis</h4>\n          <div class="metrics-grid">\n            <div class="metric-item">\n              <span class="metric-label">Annual Revenue:</span>\n              <span class="metric-value">${e(w)}</span>\n            </div>\n            <div class="metric-item">\n              <span class="metric-label">Annual Profit:</span>\n              <span class="metric-value">${e(E)}</span>\n            </div>\n            <div class="metric-item">\n              <span class="metric-label">Capacity Utilization:</span>\n              <span class="metric-value">${n(P)}</span>\n            </div>\n            <div class="metric-item">\n              <span class="metric-label">Revenue per sq ft:</span>\n              <span class="metric-value">${e(C)}/month</span>\n            </div>\n            <div class="metric-item">\n              <span class="metric-label">Revenue per Seat:</span>\n              <span class="metric-value">${e($/l)}/month</span>\n            </div>\n            <div class="metric-item">\n              <span class="metric-label">Cost of Goods:</span>\n              <span class="metric-value">${e(h)}/month</span>\n            </div>\n          </div>\n        </div>\n\n        ${D.length>0?`\n          <div class="recommendations">\n            <h4>💡 Optimization Recommendations</h4>\n            <ul>\n              ${D.map(e=>`<li>${e}</li>`).join("")}\n            </ul>\n          </div>\n        `:""}\n\n        <div class="print-section">\n          <button onclick="window.print()" class="print-btn">🖨️ Print Business Plan</button>\n          <button onclick="downloadCSV()" class="download-btn">📥 Download Data (CSV)</button>\n        </div>\n\n        <div class="disclaimer">\n          <p><small>⚠️ Calculations are approximate and based on input data. Actual results may vary depending on market conditions, location, and management efficiency.</small></p>\n        </div>\n        </div>\n      `,window.cafeBusinessData={"Area (sq ft)":i,"Number of Seats":l,"Total Investment ($)":g,"Annual Revenue ($)":w,"Annual Expenses ($)":12*b,"Annual Profit ($)":E,"Monthly Profit ($)":B,"Profit Margin (%)":k,"Annual ROI (%)":I,"Payback Period (years)":F,"Capacity Utilization (%)":P,"Revenue per Sq Ft ($)":C,"Average Check ($)":m,"Clients per Day":p}}),window.downloadCSV=function(){if(!window.cafeBusinessData)return;const e=Object.entries(window.cafeBusinessData).map(([e,n])=>`"${e}","${"number"==typeof n?n.toFixed(2):n}"`).join("\n"),n=new Blob(["\ufeffMetric,Value\n"+e],{type:"text/csv;charset=utf-8;"}),t=document.createElement("a");t.href=URL.createObjectURL(n),t.download="cafe-business-plan.csv",t.click()}});